                ordinal: NaN, // Set it later.
                level,
                firstLeafLocator,
                id: new Point(), // Set it in `_initCellsId`.
                span: setDimXYValue(new Point(), self.dimIdx, 1, 1),
                option: cellOption,
                xy: NaN,
                wh: NaN,
                dim: self,
                rect: createNaNRectLike(),
